let doctorId = 35;
let date = new Date().toISOString().slice(0, 10);
try {
  const parsed = typeof query === 'string' ? JSON.parse(query) : query;
  if (parsed && parsed.doctorId) doctorId = parsed.doctorId;
  if (parsed && parsed.date) date = parsed.date;
} catch (e) {
  if (!isNaN(Number(query))) doctorId = Number(query);
}
const res = await fetch(`http://host.docker.internal:8080/api/v1/appointments/doctor/${doctorId}/free-slots?date=${date}`);
const slots = await res.json();
return JSON.stringify({ doctorId, date, availableSlots: slots });
